      {capture $c_1}
        {=og_text(og_get($v_d, ['name']))}
      {/capture}
      {=og_include('compose/Text.latte', ['size' => 'lg', 'weight' => 'semibold', 'children' => (string) $c_1])|noescape}
      {capture $c_2}
        {=og_text(og_get($v_d, ['summary']))}
      {/capture}
      {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
      {capture $c_12}
        {capture $c_5}
          {capture $c_3}
            {=og_text(og_get($v_labels, ['weight']))}
          {/capture}
          {=og_include('compose/Inline.latte', ['class' => 'text-muted-foreground', 'children' => (string) $c_3])|noescape}
          {capture $c_4}
            {=og_text(og_get($v_d, ['weight']))}
          {/capture}
          {=og_include('compose/Inline.latte', ['class' => 'font-semibold', 'children' => (string) $c_4])|noescape}
        {/capture}
        {=og_include('compose/ListItem.latte', ['class' => 'flex items-center justify-between gap-4', 'children' => (string) $c_5])|noescape}
        {capture $c_8}
          {capture $c_6}
            {=og_text(og_get($v_labels, ['heat']))}
          {/capture}
          {=og_include('compose/Inline.latte', ['class' => 'text-muted-foreground', 'children' => (string) $c_6])|noescape}
          {capture $c_7}
            {=og_text(og_get($v_d, ['tag']))}
          {/capture}
          {=og_include('compose/Inline.latte', ['class' => 'font-semibold', 'children' => (string) $c_7])|noescape}
        {/capture}
        {=og_include('compose/ListItem.latte', ['class' => 'flex items-center justify-between gap-4', 'children' => (string) $c_8])|noescape}
        {capture $c_11}
          {capture $c_9}
            {=og_text(og_get($v_labels, ['price']))}
          {/capture}
          {=og_include('compose/Inline.latte', ['class' => 'text-muted-foreground', 'children' => (string) $c_9])|noescape}
          {capture $c_10}
            {=og_text(og_money(og_get($v_d, ['price']), og_get($v_d, ['currency'])))}
          {/capture}
          {=og_include('compose/Inline.latte', ['class' => 'font-semibold', 'children' => (string) $c_10])|noescape}
        {/capture}
        {=og_include('compose/ListItem.latte', ['class' => 'flex items-center justify-between gap-4', 'children' => (string) $c_11])|noescape}
      {/capture}
      {=og_include('compose/List.latte', ['tag' => 'ul', 'class' => 'flex flex-col gap-2 text-sm', 'children' => (string) $c_12])|noescape}
      {capture $c_13}
        {=og_include('icons/LucideIcon.latte', ['name' => 'timer', 'size' => 16])|noescape}
        {=og_text(og_tpl(og_get($v_labels, ['minutes']), [og_str(og_get($v_d, ['minutes']))]))}
      {/capture}
      {=og_include('compose/Badge.latte', ['variant' => 'secondary', 'size' => 'default', 'class' => 'w-fit', 'children' => (string) $c_13])|noescape}
    {/capture}
